import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ShieldCheck, Save } from "lucide-react";
import { motion } from "framer-motion";

export default function NewEntryPage() {
  const navigate = useNavigate();
  const [title, setTitle] = useState("");
  const [entry, setEntry] = useState("");
  const [mood, setMood] = useState("happy");

  const handleSave = () => {
    // Save logic with encryption could go here
    alert("✅ Entry saved securely!");
    navigate("/student-dashboard");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-pink-500 via-purple-500 to-indigo-500 flex flex-col items-center p-6">
      <motion.h1
        className="text-3xl font-extrabold text-white mt-6 mb-6 drop-shadow-lg"
        initial={{ opacity: 0, y: -40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        ✍️ Create a New Secure Entry
      </motion.h1>

      <Card className="w-full max-w-3xl shadow-2xl rounded-2xl">
        <CardContent className="p-6 space-y-6">
          <div>
            <label className="block text-gray-700 font-semibold mb-2">
              Title
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Give your entry a title..."
              className="w-full border border-gray-300 rounded-xl px-4 py-3 focus:ring-2 focus:ring-purple-400 outline-none"
            />
          </div>

          <div>
            <label className="block text-gray-700 font-semibold mb-2">
              Your Thoughts
            </label>
            <textarea
              value={entry}
              onChange={(e) => setEntry(e.target.value)}
              placeholder="Write your diary entry here..."
              rows={8}
              className="w-full border border-gray-300 rounded-xl px-4 py-3 focus:ring-2 focus:ring-purple-400 outline-none"
            />
          </div>

          <div>
            <label className="block text-gray-700 font-semibold mb-2">
              Mood
            </label>
            <select
              value={mood}
              onChange={(e) => setMood(e.target.value)}
              className="w-full border border-gray-300 rounded-xl px-4 py-3 focus:ring-2 focus:ring-purple-400 outline-none"
            >
              <option value="happy">😊 Happy</option>
              <option value="sad">😢 Sad</option>
              <option value="excited">🤩 Excited</option>
              <option value="angry">😡 Angry</option>
              <option value="thoughtful">🤔 Thoughtful</option>
            </select>
          </div>

          <div className="flex justify-between items-center">
            <Button
              onClick={() => navigate("/student-dashboard")}
              className="bg-gray-600 hover:bg-gray-700 text-white px-6"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              className="bg-green-600 hover:bg-green-700 text-white px-6 flex items-center"
            >
              <Save className="mr-2" /> Save Entry
            </Button>
          </div>
        </CardContent>
      </Card>

      <div className="flex items-center mt-6 text-white opacity-90">
        <ShieldCheck className="mr-2" />
        <p>Your entries are encrypted and stored securely 🔐</p>
      </div>
    </div>
  );
}
